// Check that %u works for a string constant whose vector value exactly
// fills the VPI result buffer (2048 characters).

module test;
  reg [8*2048-1:0] text;

  initial begin
    $sformat(text, "%u", "");
    if (text !== {512{"ABCD"}})
      $display("FAILED");
    else
      $display("PASSED");
  end
endmodule
